-- CRX public-schema ACL lockdown at live high-water 20260727174805.
-- Apply immediately after the public schema baseline, before the platform overlay.
--
-- A schema dump can only GRANT. A new Supabase project already grants `anon`
-- full CRUD on every table and EXECUTE on every function through
-- ALTER DEFAULT PRIVILEGES, and `REVOKE ... FROM PUBLIC` does not strip a
-- role-specific grant. Restoring the schema alone therefore leaves the
-- unauthenticated role holding privileges production revoked. This file resets
-- the managed roles and reproduces production exactly.

BEGIN;

DO $baseline_acl_roles$
BEGIN
  IF EXISTS (
    SELECT 1 FROM unnest(ARRAY['anon', 'authenticated', 'service_role', 'metabase_ro']) AS required(rolname)
    WHERE NOT EXISTS (SELECT 1 FROM pg_roles r WHERE r.rolname = required.rolname)
  ) THEN
    RAISE EXCEPTION 'BASELINE_ACL_RESTORE_REQUIRES_MANAGED_ROLES';
  END IF;
END;
$baseline_acl_roles$;

-- Reset: strip everything the target may have granted on its own.
REVOKE ALL ON ALL TABLES IN SCHEMA "public" FROM PUBLIC, anon, authenticated, service_role, metabase_ro;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA "public" FROM PUBLIC, anon, authenticated, service_role, metabase_ro;
REVOKE ALL ON ALL ROUTINES IN SCHEMA "public" FROM PUBLIC, anon, authenticated, service_role, metabase_ro;
ALTER DEFAULT PRIVILEGES FOR ROLE "postgres" IN SCHEMA "public" REVOKE ALL ON TABLES FROM PUBLIC, anon, authenticated, service_role, metabase_ro;
ALTER DEFAULT PRIVILEGES FOR ROLE "postgres" IN SCHEMA "public" REVOKE ALL ON SEQUENCES FROM PUBLIC, anon, authenticated, service_role, metabase_ro;
ALTER DEFAULT PRIVILEGES FOR ROLE "postgres" IN SCHEMA "public" REVOKE ALL ON ROUTINES FROM PUBLIC, anon, authenticated, service_role, metabase_ro;

-- Reproduce production.
